window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-744a65c001393f5e"]={"versions": [{"id": "FIG-744a65c001393f5e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR Adaptive Platform (TPS Manifest Specification, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Ethernet-Netzwerkendpunkt- und Transportkonfiguration (<code>PlatformModuleEthernetEndpointConfiguration</code>) für Plattformmodule – spezifisch instanziiert über <code>IdsPlatformInstantiation</code> zur exkulpierenden Übertragung von Security Events (Intrusion Detection System / IdsM Reporting an SIEM/Backend oder fahrzeugzentrale IDS-Knoten gemäß <code>RS_MANI_00069</code> und <code>TPS_MANI_03332</code>).</li>\n<li><strong>Systemische Einordnung:</strong> Bindeglied im Manifest-Modell zwischen der logischen Plattform-Modulinstanziierung (<code>NonOsModuleInstantiation</code>), der physischen/logischen Netzwerkanbindung des Host-Controllers (<code>EthernetCommunicationConnector</code>, <code>NetworkEndpoint</code>) und den Remote-Empfänger-Endpunkten (<code>RemoteEndpointConfiguration</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Vererbungshierarchien</p>\n<ol class=\"fig-list\">\n<li><strong><code>IdsPlatformInstantiation</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert die abstrakte Metaklasse <code>NonOsModuleInstantiation</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert die Bereitstellung und Konfiguration des Intrusion Detection System Platform Modules auf einer Adaptive-Maschine.</li>\n<li><strong>Relation:</strong> Komposition <code>+networkInterface</code> [0..\\*] zu <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PlatformModuleEthernetEndpointConfiguration</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>PlatformModuleEndpointConfiguration</code>.</li>\n<li><strong>Rolle:</strong> Zentrales Aggregat für die netzwerkseitige Endpunkt-Parametrierung von Plattformmodulen.</li>\n<li><strong>Relationen:</strong></li>\n<li>Komposition <code>+remoteConfig</code> [0..\\*] auf <code>RemoteEndpointConfiguration</code>.</li>\n<li>Assoziation <code>+tcpPort</code> [0..1] auf <code>ApApplicationEndpoint</code> (Ziel für TCP-basierte Kommunikation).</li>\n<li>Assoziation <code>+udpPort</code> [0..1] auf <code>ApApplicationEndpoint</code> (Ziel für UDP-basierte Kommunikation).</li>\n<li>Assoziation <code>+communicationConnector</code> [0..1] auf <code>EthernetCommunicationConnector</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>RemoteEndpointConfiguration</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rolle:</strong> Spezifiziert die Adress- und Portparameter des Kommunikationspartners (z. B. externes Security Backend / Collector).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ApApplicationEndpoint</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Logischer Layer-4-Endpunkt innerhalb des Ethernet-Konnektors für lokale Port-Zuweisung.</li>\n<li><strong>Attribute:</strong> <code>priority: PositiveInteger [0..1]</code> (VLAN/Socket-Priorisierung auf Anwendungsebene).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>EthernetCommunicationConnector</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>CommunicationConnector</code>.</li>\n<li><strong>Rolle:</strong> Bildet die Schnittstelle des Ethernet-Controllers zur Kommunikationsmatrix ab.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code> (MTU-Größe in Bytes).</li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code> (ARP/NDP-Cache-Größe).</li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code> (Aktivierung von Path MTU Discovery).</li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code> (Aging-Intervall für dynamische Path-MTU-Werte).</li>\n<li><strong>Relationen:</strong></li>\n<li>Komposition <code>+apApplicationEndpoint</code> [0..\\*] auf <code>ApApplicationEndpoint</code>.</li>\n<li>Assoziation <code>+unicastNetworkEndpoint</code> [0..\\*] auf <code>NetworkEndpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>NetworkEndpoint</code> & Adress-Spezialisierungen</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> <code>NetworkEndpoint</code> spezialisiert <code>Identifiable</code>.</li>\n<li><strong>Attribute (<code>NetworkEndpoint</code>):</strong></li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong>Komposition:</strong> <code>+networkEndpointAddress</code> [0..\\*] auf die abstrakte Basisklasse <code>NetworkEndpointAddress</code>.</li>\n<li><strong>Spezialisierungen von <code>NetworkEndpointAddress</code>:</strong></li>\n<li><strong><code>Ipv4Configuration</code>:</strong></li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>networkMask: Ip4AddressString [0..1]</code></li>\n<li><code>defaultGateway: Ip4AddressString [0..1]</code></li>\n<li><code>dnsServerAddress: Ip4AddressString [0..*]</code></li>\n<li><code>ipv4AddressSource: Ipv4AddressSourceEnum [0..1]</code> (z. B. Static, DHCP, AutoIP)</li>\n<li><code>ipAddressKeepBehavior: IpAddressKeepEnum [0..1]</code></li>\n<li><code>assignmentPriority: PositiveInteger [0..1]</code></li>\n<li><code>ttl: PositiveInteger [0..1]</code></li>\n<li><strong><code>Ipv6Configuration</code>:</strong></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>ipAddressPrefixLength: PositiveInteger [0..1]</code></li>\n<li><code>defaultRouter: Ip6AddressString [0..1]</code></li>\n<li><code>dnsServerAddress: Ip6AddressString [0..*]</code></li>\n<li><code>ipv6AddressSource: Ipv6AddressSourceEnum [0..1]</code> (z. B. Static, RouterAdvertisement, DHCPv6)</li>\n<li><code>ipAddressKeepBehavior: IpAddressKeepEnum [0..1]</code></li>\n<li><code>assignmentPriority: PositiveInteger [0..1]</code></li>\n<li><code>hopCount: PositiveInteger [0..1]</code></li>\n<li><code>enableAnycast: Boolean [0..1]</code></li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ARXML-Metamodell definiert das Diagramm die Deklarationsbasis für das Laufzeitverhalten:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Parsing & Socket-Initialisierung:</strong> Beim Hochlauf liest die Execution Management / Platform Module Initialisierung die <code>IdsPlatformInstantiation</code>. Der Netzwerkstack instanziiert das Interface basierend auf dem referenzierten <code>EthernetCommunicationConnector</code>.</li>\n<li><strong>Lokale Endpunkt-Bindung:</strong> Über <code>+unicastNetworkEndpoint</code> wird die IP-Konfiguration (IPv4/IPv6 via DHCP oder statisch) gebunden. <code>ApApplicationEndpoint</code> legt den lokalen Quell-Port (<code>tcpPort</code>/<code>udpPort</code>) fest.</li>\n<li><strong>Kanalaufbau & Event-Transmission:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt ein qualifiziertes Security-Event im IdsM auf, steuert das Modul über die aufgelöste <code>PlatformModuleEthernetEndpointConfiguration</code> den Kommunikationskanal an.</li>\n<li>Das Ziel wird synchron/asynchron über <code>RemoteEndpointConfiguration</code> (Ziel-IP + Remote TCP/UDP Port) adressiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Transport-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>UDP-Pfad:</strong> Verbindungsloser Versand serialisierter Security-Event-Frames direkt an die Remote-Adresse.</li>\n<li><strong>TCP-Pfad:</strong> Verbindungsaufbau (SYN/ACK) zum Ziel-Port vor Übertragung gesicherter Protokolle (z. B. TLS-gesichertes Syslog/IdsM-Reporting).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trennung von Lokalem und Remote-Endpunkt:</strong> <code>ApApplicationEndpoint</code> modelliert ausschließlich den <strong>lokalen</strong> Endpunkt (Host-Port, Priorität) innerhalb des <code>EthernetCommunicationConnector</code>. Der Kommunikationspartner muss zwingend über die Komposition <code>RemoteEndpointConfiguration</code> definiert werden (<code>TPS_MANI_03332</code>).</li>\n<li><strong>Transportprotokoll-Exklusivität:</strong> Die Kardinalitäten für <code>+tcpPort</code> [0..1] und <code>+udpPort</code> [0..1] ermöglichen wahlweise reine TCP-, reine UDP- oder Dual-Stack-Endpunkte für das Modul. Entwickler müssen sicherstellen, dass in der Modellierung mindestens ein Protokollpfad vollständig auf einen gültigen <code>ApApplicationEndpoint</code> aufgelöst ist.</li>\n<li><strong>Dual-Stack (IPv4 / IPv6):</strong> <code>RemoteEndpointConfiguration</code> erlaubt die parallele Angabe von IPv4- und IPv6-Adressen. Der ausführende Stack muss ein deterministisches Fallback- bzw. Priorisierungsverhalten (z. B. Happy Eyeballs oder feste Präferenz gemäß Systemkonfiguration) implementieren, falls beide Adressfamilien deklariert sind.</li>\n<li><strong>QoS und Priorisierung:</strong> Die Attribute <code>priority</code> an <code>ApApplicationEndpoint</code> und <code>NetworkEndpoint</code> determinieren das VLAN-PCP- bzw. IP-DSCP-Mapping, um sicherheitskritische IDS-Alarme gegenüber unkritischem Best-Effort-Traffic auf Schicht 2 und 3 zu priorisieren.</li>\n</ul>"}, {"id": "FIG-f20ce8a03eaff152", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR Adaptive Platform (TPS Manifest Specification, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Ethernet-Netzwerkendpunkt- und Transportkonfiguration (<code>PlatformModuleEthernetEndpointConfiguration</code>) für Plattformmodule – spezifisch instanziiert über <code>IdsPlatformInstantiation</code> zur exkulpierenden Übertragung von Security Events (Intrusion Detection System / IdsM Reporting an SIEM/Backend oder fahrzeugzentrale IDS-Knoten gemäß <code>RS_MANI_00069</code> und <code>TPS_MANI_03332</code>).</li>\n<li><strong>Systemische Einordnung:</strong> Bindeglied im Manifest-Modell zwischen der logischen Plattform-Modulinstanziierung (<code>NonOsModuleInstantiation</code>), der physischen/logischen Netzwerkanbindung des Host-Controllers (<code>EthernetCommunicationConnector</code>, <code>NetworkEndpoint</code>) und den Remote-Empfänger-Endpunkten (<code>RemoteEndpointConfiguration</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Vererbungshierarchien</p>\n<ol class=\"fig-list\">\n<li><strong><code>IdsPlatformInstantiation</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert die abstrakte Metaklasse <code>NonOsModuleInstantiation</code>.</li>\n<li><strong>Rolle:</strong> Repräsentiert die Bereitstellung und Konfiguration des Intrusion Detection System Platform Modules auf einer Adaptive-Maschine.</li>\n<li><strong>Relation:</strong> Komposition <code>+networkInterface</code> [0..*] zu <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PlatformModuleEthernetEndpointConfiguration</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>PlatformModuleEndpointConfiguration</code>.</li>\n<li><strong>Rolle:</strong> Zentrales Aggregat für die netzwerkseitige Endpunkt-Parametrierung von Plattformmodulen.</li>\n<li><strong>Relationen:</strong></li>\n<li>Komposition <code>+remoteConfig</code> [0..*] auf <code>RemoteEndpointConfiguration</code>.</li>\n<li>Assoziation <code>+tcpPort</code> [0..1] auf <code>ApApplicationEndpoint</code> (Ziel für TCP-basierte Kommunikation).</li>\n<li>Assoziation <code>+udpPort</code> [0..1] auf <code>ApApplicationEndpoint</code> (Ziel für UDP-basierte Kommunikation).</li>\n<li>Assoziation <code>+communicationConnector</code> [0..1] auf <code>EthernetCommunicationConnector</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>RemoteEndpointConfiguration</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rolle:</strong> Spezifiziert die Adress- und Portparameter des Kommunikationspartners (z. B. externes Security Backend / Collector).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ApApplicationEndpoint</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>Identifiable</code>.</li>\n<li><strong>Rolle:</strong> Logischer Layer-4-Endpunkt innerhalb des Ethernet-Konnektors für lokale Port-Zuweisung.</li>\n<li><strong>Attribute:</strong> <code>priority: PositiveInteger [0..1]</code> (VLAN/Socket-Priorisierung auf Anwendungsebene).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>EthernetCommunicationConnector</code></strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> Spezialisiert <code>CommunicationConnector</code>.</li>\n<li><strong>Rolle:</strong> Bildet die Schnittstelle des Ethernet-Controllers zur Kommunikationsmatrix ab.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code> (MTU-Größe in Bytes).</li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code> (ARP/NDP-Cache-Größe).</li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code> (Aktivierung von Path MTU Discovery).</li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code> (Aging-Intervall für dynamische Path-MTU-Werte).</li>\n<li><strong>Relationen:</strong></li>\n<li>Komposition <code>+apApplicationEndpoint</code> [0..*] auf <code>ApApplicationEndpoint</code>.</li>\n<li>Assoziation <code>+unicastNetworkEndpoint</code> [0..*] auf <code>NetworkEndpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>NetworkEndpoint</code> & Adress-Spezialisierungen</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Generalisierung:</strong> <code>NetworkEndpoint</code> spezialisiert <code>Identifiable</code>.</li>\n<li><strong>Attribute (<code>NetworkEndpoint</code>):</strong></li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong>Komposition:</strong> <code>«atpSplitable» +networkEndpointAddress</code> [0..*] auf die abstrakte Basisklasse <code>NetworkEndpointAddress</code>.</li>\n<li><strong>Spezialisierungen von <code>NetworkEndpointAddress</code>:</strong></li>\n<li><strong><code>Ipv4Configuration</code>:</strong></li>\n<li><code>assignmentPriority: PositiveInteger [0..1]</code></li>\n<li><code>defaultGateway: Ip4AddressString [0..1]</code></li>\n<li><code>dnsServerAddress: Ip4AddressString [0..*]</code></li>\n<li><code>ipAddressKeepBehavior: IpAddressKeepEnum [0..1]</code></li>\n<li><code>ipv4AddressSource: Ipv4AddressSourceEnum [0..1]</code> (z. B. Static, DHCP, AutoIP)</li>\n<li><code>networkMask: Ip4AddressString [0..1]</code></li>\n<li><code>ttl: PositiveInteger [0..1]</code></li>\n<li><code>«atpIdentityContributor» + ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><strong><code>Ipv6Configuration</code>:</strong></li>\n<li><code>assignmentPriority: PositiveInteger [0..1]</code></li>\n<li><code>defaultRouter: Ip6AddressString [0..1]</code></li>\n<li><code>dnsServerAddress: Ip6AddressString [0..*]</code></li>\n<li><code>enableAnycast: Boolean [0..1]</code></li>\n<li><code>hopCount: PositiveInteger [0..1]</code></li>\n<li><code>ipAddressKeepBehavior: IpAddressKeepEnum [0..1]</code></li>\n<li><code>ipAddressPrefixLength: PositiveInteger [0..1]</code></li>\n<li><code>ipv6AddressSource: Ipv6AddressSourceEnum [0..1]</code> (z. B. Static, RouterAdvertisement, DHCPv6)</li>\n<li><code>«atpIdentityContributor» + ipv6Address: Ip6AddressString [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ARXML-Metamodell definiert das Diagramm die Deklarationsbasis für das Laufzeitverhalten:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Parsing & Socket-Initialisierung:</strong> Beim Hochlauf liest die Execution Management / Platform Module Initialisierung die <code>IdsPlatformInstantiation</code>. Der Netzwerkstack instanziiert das Interface basierend auf dem referenzierten <code>EthernetCommunicationConnector</code>.</li>\n<li><strong>Lokale Endpunkt-Bindung:</strong> Über <code>+unicastNetworkEndpoint</code> wird die IP-Konfiguration (IPv4/IPv6 via DHCP oder statisch) gebunden. <code>ApApplicationEndpoint</code> legt den lokalen Quell-Port (<code>tcpPort</code>/<code>udpPort</code>) fest.</li>\n<li><strong>Kanalaufbau & Event-Transmission:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt ein qualifiziertes Security-Event im IdsM auf, steuert das Modul über die aufgelöste <code>PlatformModuleEthernetEndpointConfiguration</code> den Kommunikationskanal an.</li>\n<li>Das Ziel wird synchron/asynchron über <code>RemoteEndpointConfiguration</code> (Ziel-IP + Remote TCP/UDP Port) adressiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Transport-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>UDP-Pfad:</strong> Verbindungsloser Versand serialisierter Security-Event-Frames direkt an die Remote-Adresse.</li>\n<li><strong>TCP-Pfad:</strong> Verbindungsaufbau (SYN/ACK) zum Ziel-Port vor Übertragung gesicherter Protokolle (z. B. TLS-gesichertes Syslog/IdsM-Reporting).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trennung von Lokalem und Remote-Endpunkt:</strong> <code>ApApplicationEndpoint</code> modelliert ausschließlich den <strong>lokalen</strong> Endpunkt (Host-Port, Priorität) innerhalb des <code>EthernetCommunicationConnector</code>. Der Kommunikationspartner muss zwingend über die Komposition <code>RemoteEndpointConfiguration</code> definiert werden (<code>TPS_MANI_03332</code>).</li>\n<li><strong>Transportprotokoll-Exklusivität:</strong> Die Kardinalitäten für <code>+tcpPort</code> [0..1] und <code>+udpPort</code> [0..1] ermöglichen wahlweise reine TCP-, reine UDP- oder Dual-Stack-Endpunkte für das Modul. Entwickler müssen sicherstellen, dass in der Modellierung mindestens ein Protokollpfad vollständig auf einen gültigen <code>ApApplicationEndpoint</code> aufgelöst ist.</li>\n<li><strong>Dual-Stack (IPv4 / IPv6):</strong> <code>RemoteEndpointConfiguration</code> erlaubt die parallele Angabe von IPv4- und IPv6-Adressen. Der ausführende Stack muss ein deterministisches Fallback- bzw. Priorisierungsverhalten (z. B. Happy Eyeballs oder feste Präferenz gemäß Systemkonfiguration) implementieren, falls beide Adressfamilien deklariert sind.</li>\n<li><strong>QoS und Priorisierung:</strong> Die Attribute <code>priority</code> an <code>ApApplicationEndpoint</code> und <code>NetworkEndpoint</code> determinieren das VLAN-PCP- bzw. IP-DSCP-Mapping, um sicherheitskritische IDS-Alarme gegenüber unkritischem Best-Effort-Traffic auf Schicht 2 und 3 zu priorisieren.</li>\n</ul>"}], "trans": [{"from": "FIG-744a65c001393f5e", "to": "FIG-f20ce8a03eaff152", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>NetworkEndpoint</code>: Komposition <code>+networkEndpointAddress</code> [0..*] zu <code>NetworkEndpointAddress</code> mit Stereotyp <code>«atpSplitable»</code> annotiert.</li>\n<li><code>Ipv4Configuration</code>: Attribut <code>ipv4Address: Ip4AddressString [0..1]</code> mit Stereotyp <code>«atpIdentityContributor»</code> annotiert.</li>\n<li><code>Ipv6Configuration</code>: Attribut <code>ipv6Address: Ip6AddressString [0..1]</code> mit Stereotyp <code>«atpIdentityContributor»</code> annotiert.</li>\n</ul>"}]};
